-- folded migration: migrations/postgres/0047_payment_runtime_shape_guard.up.sql
-- sdkwork:migration
-- id: 0047_payment_runtime_shape_guard
-- engine: postgres
-- module: sdkwork-cloudrouter
-- purpose: Converge the federated commerce_payment_intent / commerce_payment_attempt shape with the Cloud Router payment runtime projections.
-- reversible: false
-- rollback: forward-fix
-- transactional: true
-- lock: exclusive
-- lock_timeout: 2s
-- statement_timeout: 30s
-- contract_version: 0.5.0
--
-- Ownership boundary: `commerce_payment_intent` and `commerce_payment_attempt`
-- are owned by the federated `sdkwork-payment` module, which is installed
-- before Cloud Router's own modules. Cloud Router's payment runtime projects a
-- provider-dispatch payload (`next_action_json`/`provider_native_json`), the
-- merchant order reference, and the two pre-confirmation statuses onto those
-- facts. The retired `payment-runtime` module used to declare a wider shape;
-- when it was retired the projections stopped being provisioned and every
-- payment-intent insert failed on a freshly installed database.
--
-- This guard is additive and idempotent: it only runs when the federated table
-- already exists, never creates or drops a table, and is a no-op when the
-- owning baseline already carries the columns. The owning repository remains
-- the authority; this migration must be removed once sdkwork-payment ships the
-- same columns in its own baseline.
DO $$
BEGIN
    IF to_regclass('commerce_payment_intent') IS NULL THEN
        RETURN;
    END IF;

    ALTER TABLE commerce_payment_intent
        ADD COLUMN IF NOT EXISTS merchant_order_no TEXT NOT NULL DEFAULT '';
    ALTER TABLE commerce_payment_intent
        ADD COLUMN IF NOT EXISTS subject TEXT NOT NULL DEFAULT '';
    ALTER TABLE commerce_payment_intent
        ADD COLUMN IF NOT EXISTS provider TEXT NOT NULL DEFAULT '';
    ALTER TABLE commerce_payment_intent
        ADD COLUMN IF NOT EXISTS supplier_code TEXT NOT NULL DEFAULT '';
    ALTER TABLE commerce_payment_intent
        ADD COLUMN IF NOT EXISTS scene_code TEXT NOT NULL DEFAULT '';
    ALTER TABLE commerce_payment_intent
        ADD COLUMN IF NOT EXISTS metadata_json JSONB NOT NULL DEFAULT '{}'::jsonb;
    ALTER TABLE commerce_payment_intent
        ADD COLUMN IF NOT EXISTS provider_native_json JSONB;
    ALTER TABLE commerce_payment_intent
        ADD COLUMN IF NOT EXISTS next_action_json JSONB;
    ALTER TABLE commerce_payment_intent
        ADD COLUMN IF NOT EXISTS captured_amount NUMERIC(18, 2) NOT NULL DEFAULT 0;
    ALTER TABLE commerce_payment_intent
        ADD COLUMN IF NOT EXISTS refunded_amount NUMERIC(18, 2) NOT NULL DEFAULT 0;

    ALTER TABLE commerce_payment_intent
        DROP CONSTRAINT IF EXISTS commerce_payment_intent_status_check;
    ALTER TABLE commerce_payment_intent
        ADD CONSTRAINT commerce_payment_intent_status_check
        CHECK (status IN (
            'created', 'pending', 'processing', 'succeeded', 'failed',
            'canceled', 'closed', 'requires_confirmation', 'requires_action'
        ));
END $$;

DO $$
BEGIN
    IF to_regclass('commerce_payment_attempt') IS NULL THEN
        RETURN;
    END IF;

    ALTER TABLE commerce_payment_attempt
        ADD COLUMN IF NOT EXISTS provider TEXT NOT NULL DEFAULT '';

    ALTER TABLE commerce_payment_attempt
        DROP CONSTRAINT IF EXISTS commerce_payment_attempt_status_check;
    ALTER TABLE commerce_payment_attempt
        ADD CONSTRAINT commerce_payment_attempt_status_check
        CHECK (status IN (
            'created', 'pending', 'processing', 'succeeded', 'failed',
            'canceled', 'closed', 'requires_confirmation', 'requires_action'
        ));
END $$;

DO $$
BEGIN
    IF to_regclass('commerce_refund_event') IS NULL THEN
        RETURN;
    END IF;

    -- Cloud Router records the operator/system reason on the refund event; the
    -- federated shape keeps only the coded reason on `commerce_refund`.
    ALTER TABLE commerce_refund_event ADD COLUMN IF NOT EXISTS reason TEXT;
END $$;

-- folded migration: migrations/postgres/0048_soft_delete_active_unique_indexes.up.sql
-- sdkwork:migration
-- id: 0048_soft_delete_active_unique_indexes
-- engine: postgres
-- module: sdkwork-cloudrouter
-- purpose: Make the user-preference and webhook-endpoint natural keys unique among active rows only, so a deleted row no longer blocks re-creating the same key.
-- reversible: false
-- rollback: forward-fix
-- transactional: true
-- lock: exclusive
-- lock_timeout: 2s
-- statement_timeout: 30s
-- contract_version: 0.5.0
--
-- Both tables use soft delete. Their natural-key unique indexes previously
-- covered deleted rows too, so a user who removed a webhook endpoint could
-- never re-create the same `endpoint_code`. The registry now declares
-- `soft_delete_policy: active_unique`; the compiler emits the partial
-- predicate for clean installs and this migration converges existing ones.
-- The old index made duplicate active keys impossible, so the rebuild needs no
-- de-duplication pass and cannot fail on existing data.
DROP INDEX IF EXISTS uk_iam_user_preference_scope;
CREATE UNIQUE INDEX IF NOT EXISTS uk_iam_user_preference_scope
    ON iam_user_preference (tenant_id, organization_id, user_id)
    WHERE deleted_at IS NULL;

DROP INDEX IF EXISTS uk_integration_webhook_endpoint_scope_code;
CREATE UNIQUE INDEX IF NOT EXISTS uk_integration_webhook_endpoint_scope_code
    ON integration_webhook_endpoint (tenant_id, organization_id, endpoint_code)
    WHERE deleted_at IS NULL;

-- folded migration: migrations/postgres/0049_retire_legacy_routing_control_plane.up.sql
-- sdkwork:migration
-- id: 0049_retire_legacy_routing_control_plane
-- engine: postgres
-- module: sdkwork-cloudrouter
-- purpose: Retire the routing control plane that the invocation selector no
--   longer reads, and align the seeded default group with the documented
--   price-first strategy.
--
--   The pre-rewrite routing policy/profile/rule tables and the
--   ai_routing_strategy table have no production reader: strategy selection is
--   the closed UpstreamAccountRoutingStrategy enum configured on
--   ai_upstream_account_group.routing_strategy and optionally overridden by
--   iam_gateway_api_key_account_group.routing_strategy. Keeping the tables and
--   the duplicate routing_strategy_code / routing_policy_id columns invited
--   two sources of truth and stale annotations.
--
--   The UPDATE runs before the column drops so existing installations keep the
--   corrected price-first default. The migration is irreversible (forward fix).
-- reversible: false
-- rollback: forward-fix
-- transactional: true
-- lock: exclusive
-- lock_timeout: 2s
-- statement_timeout: 30s

BEGIN;

-- The old seed wrote routing_strategy='weighted' while the annotation said
-- price_first. The selector reads routing_strategy only, so the documented
-- cheapest-account default was never applied.
UPDATE ai_upstream_account_group
SET routing_strategy = 'least_cost',
    version = version + 1,
    updated_at = CURRENT_TIMESTAMP
WHERE metadata ->> 'itemType' = 'default_admin_upstream_account_group'
  AND group_code = 'default-group'
  AND deleted_at IS NULL
  AND routing_strategy = 'weighted';

-- Dead routing identity columns: the decision log never persists a policy,
-- profile, or rule identity after the control-plane retirement.
ALTER TABLE ai_routing_decision_log
    DROP COLUMN IF EXISTS policy_id,
    DROP COLUMN IF EXISTS profile_id,
    DROP COLUMN IF EXISTS rule_id;

-- The group strategy is the closed enum in routing_strategy. The legacy
-- strategy-code annotation and the policy FK duplicated it and drifted.
ALTER TABLE ai_upstream_account_group
    DROP COLUMN IF EXISTS routing_strategy_code,
    DROP COLUMN IF EXISTS routing_policy_id;

-- Child tables first so the existing foreign keys never block the drop.
DROP TABLE IF EXISTS ai_routing_rule;
DROP TABLE IF EXISTS ai_routing_profile;
DROP TABLE IF EXISTS ai_routing_policy;
DROP TABLE IF EXISTS ai_routing_strategy;

COMMIT;

-- folded migration: migrations/postgres/0050_converge_routing_strategy_default_and_check.up.sql
-- sdkwork:migration
-- id: 0050_converge_routing_strategy_default_and_check
-- engine: postgres
-- module: sdkwork-cloudrouter
-- purpose: Converge ai_upstream_account_group.routing_strategy on existing installations with the contract the regenerated baseline already carries: the column default becomes least_cost and the CHECK enumerates the full closed strategy set.
-- reversible: false
-- rollback: forward-fix
-- transactional: true
-- lock: exclusive
-- lock_timeout: 2s
-- statement_timeout: 30s
--
-- Databases installed before the baseline regeneration carry the old
-- `weighted` default and a CHECK without `least_cost`, so a row inserted
-- without an explicit strategy stores `weighted` even though the selector
-- documented price-first as the default. This migration converges the column
-- default and constraint for those installations; the regenerated baseline
-- carries the same definition for clean installs.
ALTER TABLE ai_upstream_account_group
    ALTER COLUMN routing_strategy SET DEFAULT 'least_cost';

ALTER TABLE ai_upstream_account_group
    DROP CONSTRAINT IF EXISTS ck_ai_upstream_account_group_routing_strategy;

ALTER TABLE ai_upstream_account_group
    ADD CONSTRAINT ck_ai_upstream_account_group_routing_strategy
        CHECK (routing_strategy IN ('weighted', 'round_robin', 'least_latency', 'least_cost', 'quality_first', 'failover'));

