CREATE INDEX IF NOT EXISTS ix_storage_gc_job_scope_created ON storage_gc_job (tenant_id, organization_id, status, id);
CREATE INDEX IF NOT EXISTS ix_storage_gc_job_uuid ON storage_gc_job (uuid);

